Script2:
SuspendAtlasInput(); DisableTargetable();
LoadAtlas( AtlasGenericStart, 48 );
PanAtlas( AtlasKingsmarch, 3 );
RequestAtlasTalk( Farrow_ComeToKingsmarchP2, AtlasKingsmarch );
Delay( 2.0, {EnableTargetable();});
Delay( 10, {triggerer.SetGlobalAudioParam( MusicInterlude, 2 );});

SuspendAtlasInput(); LoadAtlas( ChayulaLeague, 48 ); 
triggerer.SetGlobalAudioParam( MusicInterlude, 0 );
DelayIgnoringPause (2, { triggerer.PlayInterlude ( 'Audio/Music/Endgame/Leagues/Breach/Stingers/AilithAtlas', 0.5 ); } );
PanAtlas( ChayulaLeague_TowerBoss, 2.8, 0.6 ); DelayIgnoringPause( 3.5, { RequestAtlasTalk( Ailith_OnNextStepP2, ChayulaLeague_TowerBoss ); } );

Script:
triggerer.FinishNPCChat(); triggerer.InterruptIndefinitely( ChayulaAscend );
triggerer.Delay( 1.0, { SetQuestFlag(ChayulaAlternateSkin); });
triggerer.Delay( 6, { EndIndefiniteInterrupt( ChayulaAscendEnd ); });
triggerer.Delay( 8, { triggerer.SendOpenScreen( CharacterPassiveTreeScreen, 1 ); } );
